+func TestError_ToGRPCStatus(t *testing.T) {
+	httpStatus := http.StatusTooManyRequests
+	otherOTLPHTTPStatus := http.StatusOK
+	serverErr := status.New(codes.ResourceExhausted, errTest.Error())
+	testCases := []struct {
+		name       string
+		httpStatus int
+		grpcStatus *status.Status
+		retryable  bool
+		want       *status.Status
+		hasCode    bool
+	}{
